-- 시드에서 ID를 직접 넣었으므로 자동 증가 시작값을 현재 최댓값 다음으로 맞춘다
ALTER TABLE MEMBER_MONTHLY_INPUT MODIFY (INPUT_ID GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE));
